class Solution { fun minimumOperations(nums:IntArray,start:Int,goal:Int):Int{if(start==goal)return 0;val visited=BooleanArray(1001);val queue=java.util.ArrayDeque<Int>();queue.add(start);visited[start]=true;var steps=0;while(queue.isNotEmpty()){repeat(queue.size){val value=queue.removeFirst();for(num in nums)for(next in intArrayOf(value+num,value-num,value xor num)){if(next==goal)return steps+1;if(next in 0..1000&&!visited[next]){visited[next]=true;queue.add(next)}}};steps++};return -1} }
